def dictionary(language):
    index = LANGUAGES.index(language)
    result = {f"advisor_{key}": values[index] for key, values in TEXT.items()}
    for rule, (title, action) in RULES.items():
        result[f"advisor_rule_{rule}"] = title[index]
        result[f"advisor_action_{rule}"] = action[index]
    result["advisor_action_position_review"] = result["advisor_action_dominance"]
    return result
